$(document).on("WebPlayerSeIniciaSistema",function(){var controles=ObtenerControles(["btnSolicitarCita","btnGestionarCita"]);if(!controles||!controles.length){return;}
var rutaImagenes=Ciel.MPC.WebPlayer.RutaRecursos+"img/Inicio/";var imgControles={"btnSolicitarCita":"btnSolicitarCita.svg","btnGestionarCita":"btnGestionarCita.svg","default":"icon-help.svg"};controles.forEach(function(control){if(control.DivContenedor==undefined){return;}
var elemento=control.DivContenedor[0];if(!elemento){return;}
var rutaImagen=imgControles[control.Nombre];if(!rutaImagen){rutaImagen=imgControles["default"];}
var imgCola=document.createElement("img");imgCola.setAttribute('src',rutaImagenes+rutaImagen);var divContentImg=document.createElement("div");divContentImg.classList.add('content-ImgBtnInicio');divContentImg.append(imgCola);elemento.prepend(divContentImg);});});